//! The generated reference pages (`docs/reference/*.md`). Each renderer
//! takes plain data and returns the page, with front matter, so the pages
//! are byte-for-byte reproducible and a test can check they're current.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use serde::Deserialize;

use crate::metrics_scan::Metric;

/// The note at the top of every generated page.
pub const GENERATED: &str =
    "<!-- Generated by `cargo run -p sprig-docs-gen`; don't edit by hand. -->";

fn front(title: &str, audience: &[&str], source: &str) -> String {
    format!(
        "---\ntitle: {title}\naudience: [{}]\ngenerated: true\nsource: {source}\n---\n\n{GENERATED}\n\n",
        audience.join(", ")
    )
}

/// Markdown table cell text: pipes escaped, newlines flattened.
fn cell(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}

// ---- settings ----

/// One setting, as the registry declares it.
#[derive(Debug, Clone, PartialEq)]
pub struct SettingDoc {
    /// `component.name`.
    pub key: String,
    /// `bool`, `int`, `float` or `text`.
    pub kind: String,
    /// The built-in default, as text.
    pub default: String,
    /// Scope names: object, database, tenant, cluster, dc, global.
    pub scopes: Vec<String>,
    /// Hard bounds as text ("1 to 100", "on, off"), or empty.
    pub bounds: String,
    /// `live`, `new sessions` or `rebind`.
    pub apply: String,
    /// Tenants may not set it.
    pub operator_only: bool,
    /// The one-line description.
    pub doc: String,
}

/// `docs/reference/settings.md`.
#[must_use]
pub fn settings_page(settings: &[SettingDoc]) -> String {
    let mut out = front(
        "Settings",
        &["dba", "operator"],
        "the settings registry (sprig-settings)",
    );
    out.push_str(
        "Every setting SprigDB declares, with its default, the scopes that may set it, hard \
         bounds and when a change applies. Settings resolve from the most specific scope: \
         object, database, tenant and its ancestors, cluster, data center, global, then the \
         built-in default. Read and change them with `SHOW SETTINGS`, `SET SETTING` and \
         `sprigctl settings`.\n\n",
    );
    let mut groups: BTreeMap<&str, Vec<&SettingDoc>> = BTreeMap::new();
    for s in settings {
        let g = s.key.split('.').next().unwrap_or(&s.key);
        groups.entry(g).or_default().push(s);
    }
    let _ = writeln!(
        out,
        "{} settings in {} groups.\n",
        settings.len(),
        groups.len()
    );
    for (g, list) in &groups {
        let _ = writeln!(out, "## `{g}`\n");
        out.push_str("| Key | Type | Default | Scopes | Bounds | Applies | Description |\n");
        out.push_str("|---|---|---|---|---|---|---|\n");
        let mut list = list.clone();
        list.sort_by(|a, b| a.key.cmp(&b.key));
        for s in list {
            let scopes = if s.operator_only {
                format!("{} (operator only)", s.scopes.join(", "))
            } else {
                s.scopes.join(", ")
            };
            let _ = writeln!(
                out,
                "| `{}` | {} | `{}` | {} | {} | {} | {} |",
                s.key,
                s.kind,
                cell(&s.default),
                scopes,
                cell(if s.bounds.is_empty() { "-" } else { &s.bounds }),
                s.apply,
                cell(&s.doc)
            );
        }
        out.push('\n');
    }
    out
}

// ---- errors ----

/// One error code.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ErrorDoc {
    /// 39000–39999.
    pub number: u16,
    /// `ER_SPRIG_…`.
    pub name: String,
    /// The MongoDB `codeName`.
    pub mongo: String,
    /// SQLSTATE.
    pub sqlstate: String,
    /// Safe to retry.
    pub retryable: bool,
    /// HTTP status for REST.
    pub http: u16,
    /// gRPC status name.
    pub grpc: String,
}

/// The hand-kept part of an error's entry (`docs/errors-what-to-do.toml`).
#[derive(Debug, Clone, Default, Deserialize, PartialEq, Eq)]
pub struct ErrorHelp {
    /// What it means.
    #[serde(default)]
    pub meaning: String,
    /// What to do about it.
    #[serde(default)]
    pub what_to_do: String,
}

/// Reads `errors-what-to-do.toml`: `[ER_SPRIG_NAME] meaning = … what_to_do = …`.
///
/// # Errors
/// The file isn't valid TOML of that shape.
pub fn parse_error_help(text: &str) -> Result<BTreeMap<String, ErrorHelp>, String> {
    toml::from_str(text).map_err(|e| e.to_string())
}

/// `docs/reference/errors.md`.
#[must_use]
pub fn errors_page(errors: &[ErrorDoc], help: &BTreeMap<String, ErrorHelp>) -> String {
    let mut out = front(
        "Error codes",
        &["user", "dba", "operator"],
        "SprigCode::ALL (sprig-common) and docs/errors-what-to-do.toml",
    );
    out.push_str(
        "SprigDB's own errors use numbers 39000–39999. MySQL and MariaDB clients receive the \
         number and SQLSTATE; MongoDB clients receive the same number with the `codeName`; \
         the REST API answers with the HTTP status and the gRPC API with the status shown. \
         Errors marked retryable are safe to retry as they are. Some drivers show these \
         numbers as negative (a signed 16-bit value): add 65536.\n\n",
    );
    let mut list = errors.to_vec();
    list.sort_by_key(|e| e.number);
    let _ = writeln!(out, "{} codes.\n", list.len());
    out.push_str("| Code | Name | SQLSTATE | Retry | HTTP | gRPC | Meaning and what to do |\n");
    out.push_str("|---|---|---|---|---|---|---|\n");
    for e in &list {
        let h = help.get(&e.name).cloned().unwrap_or_default();
        let text = match (h.meaning.is_empty(), h.what_to_do.is_empty()) {
            (true, true) => String::from("-"),
            (false, true) => h.meaning,
            (true, false) => format!("**Do:** {}", h.what_to_do),
            (false, false) => format!("{} **Do:** {}", h.meaning, h.what_to_do),
        };
        let _ = writeln!(
            out,
            "| {} | `{}`<br>`{}` | {} | {} | {} | {} | {} |",
            e.number,
            e.name,
            e.mongo,
            e.sqlstate,
            if e.retryable { "yes" } else { "no" },
            e.http,
            e.grpc,
            cell(&text)
        );
    }
    out
}

// ---- metrics ----

/// The hand-kept help line of a metric (`docs/metrics-help.toml`:
/// `sprig_name = "help"`).
///
/// # Errors
/// The file isn't a TOML table of strings.
pub fn parse_metric_help(text: &str) -> Result<BTreeMap<String, String>, String> {
    toml::from_str(text).map_err(|e| e.to_string())
}

/// `docs/reference/metrics.md`.
#[must_use]
pub fn metrics_page(metrics: &[Metric], help: &BTreeMap<String, String>) -> String {
    let mut out = front(
        "Metrics",
        &["operator"],
        "the metric macros in the source tree, and docs/metrics-help.toml",
    );
    out.push_str(
        "Every metric SprigDB records, as exported on each process's telemetry port \
         (`/metrics`, Prometheus text) and through OTLP. Counters end in `_total`; durations \
         are histograms in seconds.\n\n",
    );
    let mut groups: BTreeMap<String, Vec<&Metric>> = BTreeMap::new();
    for m in metrics {
        let g = m
            .name
            .trim_start_matches("sprig_")
            .split('_')
            .next()
            .unwrap_or("")
            .to_owned();
        groups.entry(g).or_default().push(m);
    }
    let _ = writeln!(
        out,
        "{} metrics in {} groups.\n",
        metrics.len(),
        groups.len()
    );
    for (g, list) in &groups {
        let _ = writeln!(out, "## `sprig_{g}_*`\n");
        out.push_str(
            "| Metric | Type | Labels | Recorded by | Description |\n|---|---|---|---|---|\n",
        );
        for m in list {
            let kinds: Vec<&str> = m.kinds.iter().map(|k| k.as_str()).collect();
            let labels: Vec<String> = m.labels.iter().map(|l| format!("`{l}`")).collect();
            let crates: Vec<&str> = m.crates.iter().map(String::as_str).collect();
            let _ = writeln!(
                out,
                "| `{}` | {} | {} | {} | {} |",
                m.name,
                kinds.join(", "),
                if labels.is_empty() {
                    "-".to_owned()
                } else {
                    labels.join(", ")
                },
                crates.join(", "),
                cell(help.get(&m.name).map_or("-", String::as_str))
            );
        }
        out.push('\n');
    }
    out
}

// ---- REST API ----

/// One operation of the `OpenAPI` document.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ApiOp {
    /// The tag (the service), such as `sprig.v1.Sql`.
    pub tag: String,
    /// `GET`, `POST`, …
    pub method: String,
    /// The path template.
    pub path: String,
    /// The operation id.
    pub id: String,
    /// The summary.
    pub summary: String,
}

/// `docs/reference/api.md`.
#[must_use]
pub fn api_page(ops: &[ApiOp]) -> String {
    let mut out = front(
        "REST API",
        &["user", "dba", "operator"],
        "the gateway's OpenAPI document (/v1/openapi.json)",
    );
    out.push_str(
        "The gateway's REST API, as `/v1/openapi.json` describes it on every gateway. \
         Requests authenticate with `Authorization: Bearer <token or API key>` (or HTTP Basic \
         where allowed) and act with the caller's own rights. Statements stream as NDJSON from \
         `POST /v1/databases/{database}/sql:query`. The same services are available over \
         gRPC.\n\n",
    );
    let mut by_tag: BTreeMap<&str, Vec<&ApiOp>> = BTreeMap::new();
    for o in ops {
        by_tag.entry(o.tag.as_str()).or_default().push(o);
    }
    let _ = writeln!(
        out,
        "{} operations in {} services.\n",
        ops.len(),
        by_tag.len()
    );
    for (tag, list) in &by_tag {
        let _ = writeln!(out, "## {tag}\n");
        out.push_str("| Method | Path | Operation | Description |\n|---|---|---|---|\n");
        let mut list = list.clone();
        list.sort_by(|a, b| (&a.path, &a.method).cmp(&(&b.path, &b.method)));
        for o in list {
            let _ = writeln!(
                out,
                "| {} | `{}` | `{}` | {} |",
                o.method,
                o.path,
                o.id,
                cell(&o.summary)
            );
        }
        out.push('\n');
    }
    out
}

// ---- command-line tools ----

/// A command's help text, with its subcommands' (from `--help`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CommandHelp {
    /// `sprigctl index list`.
    pub path: String,
    /// The `--help` output.
    pub help: String,
}

/// `docs/reference/<tool>.md`: every command's help, in order.
#[must_use]
pub fn cli_page(tool: &str, intro: &str, commands: &[CommandHelp]) -> String {
    let mut out = front(
        &format!("`{tool}` commands"),
        &["dba", "operator"],
        &format!("`{tool} --help` for each command"),
    );
    out.push_str(intro);
    out.push_str("\n\n");
    for c in commands {
        let depth = c.path.split(' ').count().clamp(1, 4);
        let _ = writeln!(
            out,
            "{} `{}`\n\n```text\n{}\n```\n",
            "#".repeat(depth + 1),
            c.path,
            c.help.trim_end()
        );
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn settings_are_grouped_and_escaped() {
        let page = settings_page(&[
            SettingDoc {
                key: "studio.view_as".into(),
                kind: "text".into(),
                default: "on".into(),
                scopes: vec!["tenant".into(), "global".into()],
                bounds: "on, off".into(),
                apply: "live".into(),
                operator_only: false,
                doc: "Allow the RLS tester | yes".into(),
            },
            SettingDoc {
                key: "auto_index.min_runs".into(),
                kind: "int".into(),
                default: "50".into(),
                scopes: vec!["global".into()],
                bounds: "1 to 1000000".into(),
                apply: "live".into(),
                operator_only: true,
                doc: "Runs needed".into(),
            },
        ]);
        assert!(page.starts_with("---\ntitle: Settings\n"));
        assert!(page.find("## `auto_index`") < page.find("## `studio`"));
        assert!(page.contains("Allow the RLS tester \\| yes"));
        assert!(page.contains("global (operator only)"));
    }

    #[test]
    fn errors_merge_the_hand_kept_help() {
        let help = parse_error_help(
            "[ER_SPRIG_AI_BUDGET_EXCEEDED]\nmeaning = \"The daily budget is used up.\"\nwhat_to_do = \"Wait, or raise it.\"\n",
        )
        .unwrap();
        let page = errors_page(
            &[ErrorDoc {
                number: 39992,
                name: "ER_SPRIG_AI_BUDGET_EXCEEDED".into(),
                mongo: "SprigAiBudgetExceeded".into(),
                sqlstate: "HY000".into(),
                retryable: false,
                http: 429,
                grpc: "ResourceExhausted".into(),
            }],
            &help,
        );
        assert!(page.contains(
            "| 39992 | `ER_SPRIG_AI_BUDGET_EXCEEDED`<br>`SprigAiBudgetExceeded` | HY000 | no | 429 | ResourceExhausted | The daily budget is used up. **Do:** Wait, or raise it. |"
        ));
    }

    #[test]
    fn cli_headings_follow_depth() {
        let page = cli_page(
            "sprigctl",
            "intro",
            &[
                CommandHelp {
                    path: "sprigctl".into(),
                    help: "Usage: sprigctl".into(),
                },
                CommandHelp {
                    path: "sprigctl index list".into(),
                    help: "Usage: sprigctl index list\n".into(),
                },
            ],
        );
        assert!(page.contains("## `sprigctl`"));
        assert!(
            page.contains("#### `sprigctl index list`\n\n```text\nUsage: sprigctl index list\n```")
        );
    }
}
